def stream_rows(resource, transform):
    error_active = False
    try:
        while True:
            try:
                row = resource.read_next()
                if row is None:
                    return
                value = transform(row)
            except BaseException:
                error_active = True
                raise
            yield value
    finally:
        try:
            resource.close()
        except BaseException:
            # Cleanup must not replace an error from reading or transforming.
            if not error_active:
                raise
